export const pluginBySlug = new Map(plugins.map((plugin) => [plugin.slug, plugin]));

export const searchText = (plugin: Plugin) => Object.values(plugin)
  .flatMap((value) => Array.isArray(value) ? value : typeof value === "object" && value ? Object.entries(value).flat(2) : [String(value ?? "")])
  .join(" ")
  .toLowerCase();
